/**
* Converts a Node-API value to a double-precision floating-point number.
*
* @param env       environment under which the function is invoked
* @param value     Node-API value
* @param out       destination for storing output value
* @param message   error message
* @param err       pointer for storing a JavaScript error
* @return          status code indicating success or failure (returns `napi_ok` if success)
*
* @example
* #include "stdlib/napi/argv_double.h"
* #include <node_api.h>
*
* static napi_value addon( napi_env env, napi_callback_info info ) {
*     napi_value value;
*
*     // ...
*
*     double out;
*     napi_value err;
*     napi_status status = stdlib_napi_argv_double( env, value, &out, "Must be a number.", &err );
*     assert( status == napi_ok );
*     if ( err != NULL ) {
*         assert( napi_throw( env, err ) == napi_ok );
*         return NULL;
*     }
*
*     // ...
* }
*/
napi_status stdlib_napi_argv_double( const napi_env env, const napi_value value, double *out, const char *message, napi_value *err ) {
	stdlib_assert_napi_value_is_type( env, value, napi_number, message, err );
	if ( *err != NULL ) {
		return napi_ok;
	}
	STDLIB_ASSERT_NAPI_STATUS_OK_RET_VALUE( env, napi_get_value_double( env, value, out ), "", napi_ok )
	return napi_ok;
}","lineStart":1,"lineEnd":62,"totalLines":62,"truncated":false}},"title":"repos/pc-lib-3456/napi-argv-double/src/main.c","time":{"start":1783261796297,"end":1783261796305}},"id":"prt_f32af96c6001ip0rxyo6DHxenP","sessionID":"ses_0cd50be88ffeMefBLxc11B7M0G","messageID":"msg_f32af9026001CyL2uPEnke71jc"}}

